        List<com.steven.assets.dto.QuoteDetailDto.OrderBookLevel> levels=new ArrayList<>();for(int i=0;i<5;i++)levels.add(new com.steven.assets.dto.QuoteDetailDto.OrderBookLevel(i+1,new BigDecimal("49.99").subtract(new BigDecimal(".01").multiply(BigDecimal.valueOf(i))),10L,new BigDecimal("50").add(new BigDecimal(".05").multiply(BigDecimal.valueOf(i))),10L));com.steven.assets.dto.QuoteDetailDto.Response book=new com.steven.assets.dto.QuoteDetailDto.Response("00881","ISOLATED","台股",true,true,"FUBON_BOOKS",null,at,at,"OPEN",new BigDecimal("50"),null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,levels);body.set("book",SrppReportModuleCalculator.normalize(J.valueToTree(book)));
        ObjectNode normalized=(ObjectNode)SrppReportModuleCalculator.normalize(sources);input.set("sources",normalized);ObjectNode vector=J.createObjectNode();normalized.fields().forEachRemaining(e->{ObjectNode r=vector.putObject(e.getKey());r.put("sourceId",e.getKey()).put("revision","isolated-full-short").put("sha256",SrppJcs.hash(e.getValue())).put("capturedAt",at.toString()).put("coverage",e.getKey().equals("us-tactical")?"NONE":"COMPLETE").put("validation",e.getKey().equals("us-tactical")?"UNAVAILABLE":"VERIFIED");});var old=base.frozen().facts();var facts=new DecisionFacts.Input(date,old.slot(),at,old.sessions(),old.totalAssets(),new BigDecimal("19200000"),old.termDeposits(),old.bondValue(),old.fx(),old.fxEvidence(),old.bearWindow(),old.symbols(),old.budget(),old.subaccounts(),old.emergencyValue());return new SrppReportModuleCalculatorTest.FrozenFixture(new DecisionInputCapturePort.Frozen(facts,input,vector,15,at.toString()),base.policy(),base.registered());
